/**
 * Cascade behind `ProjectService.archiveProject`; returns the row count. Every
 * issue of the project is stamped, so the whole project leaves the live
 * listings in one statement.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )

input.new_string:
/**
 * Cascade behind `ProjectService.archiveProject`; returns the number of issues
 * it archived. Only live issues are stamped — issues archived earlier keep
 * their original `archived_at`, and are not counted, so the returned number is
 * exactly how many issues left the live listings (and the usage meter).
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )

